        ("Share repurchases", "Share repurchases", "~$400m", "~$400m", "~$400m", "~$450m", "~$450m", "met"),
        ("Diluted shares", "Diluted shares", "~51m", "~49m", "~49m", "~48m", "~48m", "met"),
