        hist_margin = hist_margin[-8:]

        def _pct_quant(vals: List[float], qv: float, fallback: float) -> float:
            if not vals:
                return float(fallback)
            s = pd.Series(vals, dtype="float64").dropna()
            if s.empty:
                return float(fallback)
            try:
                return float(s.quantile(qv))
            except Exception:
                return float(fallback)

