        lev_latest: Optional[float] = None
        if q0_latest is not None:
            gaap_ttm_latest = ebitda_ttm_map.get(q0_latest)
            adj_ttm_latest = adj_ebitda_ttm_map.get(q0_latest) if adj_ebitda_ttm_map else None
